window.CODE = Object.assign(window.CODE || {}, {"ch18/agentic_rag.py":"\"\"\"Agentic RAG as a LangGraph graph: adaptive routing + corrective retrieval + a groundedness check.\n\nroute      -> schedule questions go to the live tool, small talk needs no retrieval, policy questions to RAG\nretrieve   -> search current documents\ngrade      -> the model judges each chunk: relevant or not          (corrective RAG)\nrewrite    -> nothing relevant? rewrite the question once and search again\ngenerate   -> answer from the relevant chunks with citations\ncheck      -> is every claim supported? if not, retry once, then refuse  (self-RAG)\n\nRun:  python agentic_rag.py\n\"\"\"\nimport sys\nfrom pathlib import Path\nfrom typing import Literal, TypedDict\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import get_doctor_schedule  # noqa: E402\nfrom kb import search  # noqa: E402\nfrom langchain_core.documents import Document  # noqa: E402\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\n\nDONT_KNOW = \"I don't have that information. Please ask the front desk (1800-000-000).\"\nmodel = get_model()\n\n\nclass Route(BaseModel):\n    route: Literal[\"policy\", \"schedule\", \"smalltalk\"]\n    department: str | None = None\n\n\nclass Relevant(BaseModel):\n    relevant: bool\n\n\nclass Grounded(BaseModel):\n    grounded: bool\n    unsupported: list[str] = []\n\n\nclass State(TypedDict, total=False):\n    question: str\n    query: str\n    route: str\n    department: str\n    docs: list[Document]\n    rewritten: bool\n    answer: str\n    attempts: int\n    steps: list[str]\n\n\ndef step(state: State, name: str) -> list[str]:\n    return state.get(\"steps\", []) + [name]\n\n\n# ---------------------------------------------------------------- nodes\ndef route(state: State) -> dict:\n    r = model.with_structured_output(Route).invoke(\n        \"Route this City Clinic question. policy = rules, fees, timings, visiting, insurance, locations; \"\n        f\"schedule = which days a doctor or department works; smalltalk = greetings.\\nQuestion: {state['question']}\")\n    return {\"route\": r.route, \"department\": r.department or \"\", \"query\": state[\"question\"], \"steps\": step(state, f\"route:{r.route}\")}\n\n\ndef schedule(state: State) -> dict:\n    data = get_doctor_schedule(state[\"department\"])            # live data beats documents for schedules\n    text = model.invoke(f\"Answer from this data only, one sentence.\\nData: {data}\\nQuestion: {state['question']}\").content\n    return {\"answer\": text, \"steps\": step(state, \"schedule_tool\")}\n\n\ndef smalltalk(state: State) -> dict:\n    return {\"answer\": \"Hello! I can help with City Clinic timings, visiting rules, insurance and doctors' days.\",\n            \"steps\": step(state, \"smalltalk\")}\n\n\ndef retrieve(state: State) -> dict:\n    return {\"docs\": search(state[\"query\"], k=4, current_only=True), \"steps\": step(state, \"retrieve\")}\n\n\ndef grade(state: State) -> dict:\n    grader = model.with_structured_output(Relevant)\n    verdicts = grader.batch([f\"Question: {state['question']}\\nPassage:\\n{d.page_content}\\n\"\n                             \"Does the passage contain information that helps answer the question?\" for d in state[\"docs\"]])\n    keep = [d for d, v in zip(state[\"docs\"], verdicts) if v.relevant]\n    return {\"docs\": keep, \"steps\": step(state, f\"grade:{len(keep)}/{len(verdicts)} relevant\")}\n\n\ndef rewrite(state: State) -> dict:\n    q = model.invoke(\"Rewrite this hospital helpdesk question as a clear search query using formal words \"\n                     f\"(for example 'paediatrics' not 'kids'). Reply with the query only.\\n{state['question']}\").content\n    return {\"query\": q, \"rewritten\": True, \"steps\": step(state, f\"rewrite:'{q}'\")}\n\n\ndef generate(state: State) -> dict:\n    sources = \"\\n\\n\".join(f\"[{i}] ({d.metadata['source']})\\n{d.page_content}\" for i, d in enumerate(state[\"docs\"], 1))\n    strict = \" Use ONLY words and facts that appear in the sources.\" if state.get(\"attempts\") else \"\"\n    text = model.invoke(f\"Answer from the numbered sources only and cite them like [1]. Be brief.{strict}\\n\\n\"\n                        f\"Sources:\\n{sources}\\n\\nQuestion: {state['question']}\").content\n    return {\"answer\": text, \"attempts\": state.get(\"attempts\", 0) + 1, \"steps\": step(state, \"generate\")}\n\n\ndef check(state: State) -> dict:\n    sources = \"\\n\".join(d.page_content for d in state[\"docs\"])\n    v = model.with_structured_output(Grounded).invoke(\n        f\"Sources:\\n{sources}\\n\\nAnswer:\\n{state['answer']}\\n\\nIs every factual claim in the answer supported by the sources? \"\n        \"List unsupported claims.\")\n    if v.grounded:\n        return {\"steps\": step(state, \"check:grounded\")}\n    if state[\"attempts\"] >= 2:\n        return {\"answer\": DONT_KNOW, \"steps\": step(state, \"check:refused\")}\n    return {\"answer\": \"\", \"steps\": step(state, f\"check:unsupported {v.unsupported}\")}\n\n\ndef dont_know(state: State) -> dict:\n    return {\"answer\": DONT_KNOW, \"steps\": step(state, \"dont_know\")}\n\n\n# ---------------------------------------------------------------- edges\ndef after_grade(state: State) -> str:\n    if state[\"docs\"]:\n        return \"generate\"\n    return \"dont_know\" if state.get(\"rewritten\") else \"rewrite\"\n\n\ndef after_check(state: State) -> str:\n    return \"generate\" if state[\"answer\"] == \"\" else END\n\n\nb = StateGraph(State)\nfor name, fn in [(\"route\", route), (\"schedule\", schedule), (\"smalltalk\", smalltalk), (\"retrieve\", retrieve),\n                 (\"grade\", grade), (\"rewrite\", rewrite), (\"generate\", generate), (\"check\", check), (\"dont_know\", dont_know)]:\n    b.add_node(name, fn)\nb.add_edge(START, \"route\")\nb.add_conditional_edges(\"route\", lambda s: {\"policy\": \"retrieve\", \"schedule\": \"schedule\", \"smalltalk\": \"smalltalk\"}[s[\"route\"]],\n                        [\"retrieve\", \"schedule\", \"smalltalk\"])\nb.add_edge(\"retrieve\", \"grade\")\nb.add_conditional_edges(\"grade\", after_grade, [\"generate\", \"rewrite\", \"dont_know\"])\nb.add_edge(\"rewrite\", \"retrieve\")\nb.add_edge(\"generate\", \"check\")\nb.add_conditional_edges(\"check\", after_check, [\"generate\", END])\nfor n in (\"schedule\", \"smalltalk\", \"dont_know\"):\n    b.add_edge(n, END)\ngraph = b.compile()\n\nif __name__ == \"__main__\":\n    for q in [\"Can children visit the ICU?\", \"my kid needs shots, where do I go\", \"Which days does the orthopaedics doctor work?\",\n              \"Do you have a cafeteria?\", \"Hi there!\"]:\n        out = graph.invoke({\"question\": q})\n        print(f\"Q: {q}\\n   path:   {' -> '.join(out['steps'])}\\n   answer: {out['answer']}\\n\")\n","ch18/graph_rag.py":"\"\"\"GraphRAG in miniature: facts as a knowledge graph, so multi-hop questions can be answered.\n\n\"Which floor is the cardiologist who works on Friday?\" needs three hops:\n    Fri <-sees_patients_on- Dr Rao -works_in-> cardiology -located_on-> 2nd floor\nVector search finds passages that LOOK similar; a graph follows the links.\n\nSteps:  1. extract (subject, relation, object) triples from documents with the model\n        2. add structured data you already have (the schedule) directly\n        3. link the question's entities to graph nodes, collect their neighbourhood, answer from it\n\nRun:  pip install networkx\n      python graph_rag.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nimport networkx as nx\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import SCHEDULE  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\n\nmodel = get_model()\n\n\nclass Triple(BaseModel):\n    subject: str\n    relation: str\n    object: str\n\n\nclass Triples(BaseModel):\n    triples: list[Triple]\n\n\nclass Entities(BaseModel):\n    names: list[str]\n\n\ndef build_graph() -> nx.MultiDiGraph:\n    g = nx.MultiDiGraph()\n    # 1. From text: the model turns sentences into triples (check a sample by hand!)\n    text = (HERE / \"docs\" / \"departments.md\").read_text(encoding=\"utf-8\")\n    extracted = model.with_structured_output(Triples).invoke(\n        \"Extract facts as (subject, relation, object) triples. Use lowercase department names, relations from: \"\n        f\"located_on, in_block, has_room, has_doctor, offers.\\n\\n{text}\")\n    for t in extracted.triples:\n        g.add_edge(t.subject, t.object, relation=t.relation, source=\"departments.md\")\n    # 2. From structured data: no model needed\n    for dept, doctors in SCHEDULE.items():\n        for doctor, days in doctors.items():\n            g.add_edge(doctor, dept, relation=\"works_in\", source=\"schedule\")\n            for day in days:\n                g.add_edge(doctor, day, relation=\"sees_patients_on\", source=\"schedule\")\n    return g\n\n\ndef neighbourhood_facts(g: nx.MultiDiGraph, entities: list[str], hops: int = 2) -> list[str]:\n    \"\"\"Collect every edge within `hops` links of the question's entities (in either direction).\"\"\"\n    undirected = g.to_undirected(as_view=True)\n    nodes = set()\n    for e in entities:\n        if e in g:\n            nodes |= set(nx.single_source_shortest_path_length(undirected, e, cutoff=hops))\n    return sorted(f\"{u} --{d['relation']}--> {v}\" for u, v, d in g.edges(data=True) if u in nodes and v in nodes)\n\n\ndef ask(g: nx.MultiDiGraph, question: str) -> tuple[list[str], str]:\n    ents = model.with_structured_output(Entities).invoke(\n        f\"Which of these graph nodes does the question mention or imply? Nodes: {sorted(g.nodes)}\\nQuestion: {question}\")\n    facts = neighbourhood_facts(g, ents.names)\n    answer = model.invoke(\"Answer using only these facts. Show the chain of facts you used.\\n\"\n                          + \"\\n\".join(facts) + f\"\\n\\nQuestion: {question}\").content\n    return facts, answer\n\n\nif __name__ == \"__main__\":\n    g = build_graph()\n    print(f\"Graph: {g.number_of_nodes()} nodes, {g.number_of_edges()} edges\")\n\n    q = \"Which floor do I go to for the cardiologist who works on Friday?\"\n    facts, answer = ask(g, q)\n    print(f\"\\nQ: {q}\\nFacts found ({len(facts)}):\")\n    for f in facts:\n        print(\"  \", f)\n    print(\"A:\", answer)\n\n    # Some questions are plain graph queries; no model needed at all\n    ground = [u for u, v, d in g.edges(data=True) if d[\"relation\"] == \"located_on\" and v == \"ground floor\"]\n    print(\"\\nDepartments on the ground floor:\", ground)\n","ch18/kb.py":"\"\"\"The Chapter 18 knowledge base: clinic documents split by section, with metadata for filtering.\n\nEach chunk records its source, section, effective date and whether the document is current or\nsuperseded, because \"which version is true?\" is one of the commonest RAG failures.\n\"\"\"\nimport re\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nfrom langchain_core.documents import Document  # noqa: E402\nfrom langchain_core.vectorstores import InMemoryVectorStore  # noqa: E402\nfrom lc_models import get_embeddings  # noqa: E402\n\nDOCS = HERE / \"docs\"\n\n\ndef load_chunks() -> list[Document]:\n    chunks = []\n    for path in sorted(DOCS.glob(\"*.md\")):\n        text = path.read_text(encoding=\"utf-8\")\n        title = text.splitlines()[0].lstrip(\"# \").strip()\n        header = text.splitlines()[1]\n        effective = re.search(r\"effective ([^.]+)\", header)\n        status = \"superseded\" if \"Superseded\" in header else \"current\"\n        for section in re.split(r\"\\n(?=## )\", text)[1:]:\n            heading, _, body = section.partition(\"\\n\")\n            heading = heading.lstrip(\"# \").strip()\n            chunks.append(Document(\n                page_content=f\"{title} - {heading}\\n{body.strip()}\",\n                metadata={\"source\": f\"{path.name} > {heading}\", \"doc\": path.stem, \"status\": status,\n                          \"effective\": effective.group(1) if effective else \"\"}))\n    return chunks\n\n\nCHUNKS = load_chunks()\nstore = InMemoryVectorStore(get_embeddings())\nstore.add_documents(CHUNKS)\n\n\ndef search(query: str, k: int = 4, current_only: bool = False) -> list[Document]:\n    \"\"\"Similarity search, optionally only over current documents (a metadata filter).\"\"\"\n    flt = (lambda d: d.metadata[\"status\"] == \"current\") if current_only else None\n    return store.similarity_search(query, k=k, filter=flt)\n\n\ndef search_scored(query: str, k: int = 4, current_only: bool = True) -> list[tuple[Document, float]]:\n    \"\"\"Like search(), but also returns the cosine similarity of each chunk (1.0 = identical meaning).\"\"\"\n    flt = (lambda d: d.metadata[\"status\"] == \"current\") if current_only else None\n    return store.similarity_search_with_score(query, k=k, filter=flt)\n","ch18/rag_eval.json":"[\n  {\"question\": \"What time does OPD close in the evening?\", \"reference\": \"OPD closes at 7 pm.\", \"source\": \"opd.md > Timings\"},\n  {\"question\": \"How much is the OPD registration fee?\", \"reference\": \"Rs 100, valid for 7 days for the same doctor.\", \"source\": \"opd.md > Registration\"},\n  {\"question\": \"Can a 10-year-old visit the ICU?\", \"reference\": \"No, children under 12 may not enter the ICU.\", \"source\": \"visitors.md > ICU visits\"},\n  {\"question\": \"Which floor is the orthopaedics OPD on?\", \"reference\": \"The 1st floor, Block A.\", \"source\": \"departments.md > Orthopaedics\"},\n  {\"question\": \"Are syringes covered under PM-JAY?\", \"reference\": \"No, consumables such as syringes are not covered.\", \"source\": \"insurance.md > Not covered\"},\n  {\"question\": \"When must planned admissions be pre-authorised?\", \"reference\": \"At least 48 hours before admission.\", \"source\": \"insurance.md > Pre-authorisation\"}\n]\n","ch18/rag_eval.py":"\"\"\"Evaluate RAG with RAGAS-style metrics, and compare two retrieval set-ups on the same test set.\n\nRetrieval metrics (no model needed, because each test case names its correct source):\n  context recall     - was the correct chunk retrieved at all?\n  context precision  - how high was it ranked? (1/rank: 1.0 = first, 0.5 = second ...)\nAnswer metrics (a model acts as judge):\n  faithfulness       - are all claims supported by the retrieved chunks?\n  correctness        - does the answer agree with the reference answer?\n\nRun:  python rag_eval.py\n\"\"\"\nimport json\nfrom pathlib import Path\n\nfrom kb import search\nfrom retrieval_fixes import rerank\nfrom lc_models import get_model\nfrom pydantic import BaseModel\n\nCASES = json.loads(Path(__file__).with_name(\"rag_eval.json\").read_text())\nmodel = get_model()\n\n\nclass Verdict(BaseModel):\n    passed: bool\n    reason: str\n\n\njudge = model.with_structured_output(Verdict)\n\n\ndef answer(question: str, docs) -> str:\n    if not docs:                                   # nothing relevant: refuse without calling the model\n        return \"I don't have that information. Please ask the front desk.\"\n    sources = \"\\n\\n\".join(f\"[{i}] {d.page_content}\" for i, d in enumerate(docs, 1))\n    return model.invoke(f\"Answer from the numbered sources only, cite like [1], one sentence.\\n\\nSources:\\n{sources}\"\n                        f\"\\n\\nQuestion: {question}\").content\n\n\ndef evaluate(name: str, retriever) -> dict:\n    totals = {\"context_recall\": 0.0, \"context_precision\": 0.0, \"faithfulness\": 0.0, \"correctness\": 0.0}\n    for case in CASES:\n        docs = retriever(case[\"question\"])\n        sources = [d.metadata[\"source\"] for d in docs]\n        rank = sources.index(case[\"source\"]) + 1 if case[\"source\"] in sources else None\n        totals[\"context_recall\"] += 1 if rank else 0\n        totals[\"context_precision\"] += 1 / rank if rank else 0\n\n        reply = answer(case[\"question\"], docs)\n        context = \"\\n\".join(d.page_content for d in docs)\n        faithful = judge.invoke(f\"Context:\\n{context}\\n\\nAnswer: {reply}\\n\\nIs every claim in the answer supported by the context?\")\n        correct = judge.invoke(f\"Question: {case['question']}\\nReference: {case['reference']}\\nAnswer: {reply}\\n\\n\"\n                               \"Does the answer agree with the reference on every fact that matters (numbers, yes/no)?\")\n        totals[\"faithfulness\"] += faithful.passed\n        totals[\"correctness\"] += correct.passed\n        if not correct.passed:\n            print(f\"  [{name}] wrong: {case['question']} -> {reply}  ({correct.reason})\")\n    return {k: round(v / len(CASES), 2) for k, v in totals.items()}\n\n\nif __name__ == \"__main__\":\n    results = {\n        \"all docs, k=2\": evaluate(\"all docs, k=2\", lambda q: search(q, k=2)),\n        \"current only, k=2\": evaluate(\"current only, k=2\", lambda q: search(q, k=2, current_only=True)),\n        \"current, 5 -> rerank 2\": evaluate(\"current, 5 -> rerank 2\",\n                                           lambda q: rerank(q, search(q, k=5, current_only=True), keep=2)[0]),\n    }\n    print(f\"\\n{'set-up':<24}\" + \"\".join(f\"{m:>19}\" for m in next(iter(results.values()))))\n    for name, scores in results.items():\n        print(f\"{name:<24}\" + \"\".join(f\"{v:>19}\" for v in scores.values()))\n","ch18/retrieval_fixes.py":"\"\"\"Fixing common retrieval failures: stale documents, vague questions and weak ranking.\n\n1. Metadata filter  - search only current documents, so the 2025 OPD guide cannot win\n2. HyDE             - embed a hypothetical ANSWER instead of the short question\n3. Re-ranking       - fetch more candidates, let a model score each one, keep the best\n\nRun:  python retrieval_fixes.py\n\"\"\"\nfrom kb import search, search_scored\nfrom lc_models import get_model\nfrom pydantic import BaseModel, Field\n\nmodel = get_model()\n\n\ndef show(label: str, docs) -> None:\n    print(f\"  {label:<22}\" + \" | \".join(f\"{d.metadata['source']} ({d.metadata['status'][:3]})\" for d in docs))\n\n\n# ---------------------------------------------------------------- 2. HyDE\ndef hyde_search(question: str, k: int = 3):\n    \"\"\"Hypothetical Document Embeddings: a fake answer looks more like the real document than\n    the question does, so its embedding lands closer to the right chunk.\"\"\"\n    fake_answer = model.invoke(f\"Write two sentences that a hospital policy document might contain to \"\n                               f\"answer this question. Invent plausible details.\\nQuestion: {question}\").content\n    return search_scored(fake_answer, k=k), fake_answer\n\n\n# ---------------------------------------------------------------- 3. Re-ranking\nclass Score(BaseModel):\n    score: int = Field(ge=0, le=10, description=\"10 = directly answers the question, 0 = unrelated\")\n\n\nscorer = model.with_structured_output(Score)\n\n\ndef rerank(question: str, docs, keep: int = 2):\n    \"\"\"Score each candidate with the model (in parallel), keep the best ones.\n    A cross-encoder (sentence-transformers CrossEncoder) does the same job cheaper and faster.\"\"\"\n    prompts = [f\"Question: {question}\\n\\nPassage:\\n{d.page_content}\\n\\nHow well does the passage answer the question?\"\n               for d in docs]\n    scores = [s.score for s in scorer.batch(prompts, config={\"max_concurrency\": 5})]\n    ranked = sorted(zip(scores, docs), key=lambda p: -p[0])\n    return [d for s, d in ranked[:keep] if s >= 5], scores\n\n\nif __name__ == \"__main__\":\n    q = \"What time does OPD close on weekdays?\"\n    print(f\"Q: {q}\")\n    show(\"plain search:\", search(q, k=3))\n    show(\"current only:\", search(q, k=3, current_only=True))\n\n    q = \"my kid needs shots, where do I go\"\n    print(f\"\\nQ: {q}\")\n    plain = search_scored(q, k=3)\n    print(f\"  plain search:         {plain[0][0].metadata['source']}  similarity {plain[0][1]:.2f}\")\n    hyde, fake = hyde_search(q)\n    print(f\"  HyDE fake answer:     {fake}\")\n    print(f\"  HyDE search:          {hyde[0][0].metadata['source']}  similarity {hyde[0][1]:.2f}\")\n\n    q = \"Can my 10-year-old visit grandpa in the ICU?\"\n    print(f\"\\nQ: {q}\")\n    candidates = search(q, k=5, current_only=True)\n    show(\"top 5 candidates:\", candidates)\n    best, scores = rerank(q, candidates)\n    print(f\"  model scores:         {scores}\")\n    show(\"after re-ranking:\", best)\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
